import urllib.request, itertools, concurrent.futures

base = 'http://172.24.0.3:8081'
words = ['price','prices','pricing','sku','skus','item','items','product','products','quote','quotes','rate','rates','cost','costs','value','amount','get','fetch','lookup','query','api','v1','v2','internal','service','data','list','all','catalog','book','isbn']
