paths = set()
for w in words:
    paths.add('/'+w)
    paths.add('/'+w+'/')
for s in skus:
    for pre in ['', '/api', '/api/v1', '/v1', '/v2']:
        for w in ['price','prices','pricing','sku','item','product','quote','rate','cost']:
            paths.add(f'{pre}/{w}/{s}')
            paths.add(f'{pre}/{w}?sku={s}')
            paths.add(f'{pre}/{w}?id={s}')
def check(p):
    try:
        req = urllib.request.Request(base+p)
        with urllib.request.urlopen(req, timeout=4) as r:
            return (p, r.status, r.read()[:80])
    except urllib.error.HTTPError as e:
        return (p, e.code, None)
    except Exception as e:
        return (p, 'ERR', None)
interesting = []
with concurrent.futures.ThreadPoolExecutor(max_workers=40) as ex:
    for res in ex.map(check, sorted(paths)):
        p, code, body = res
        if code not in (404, 'ERR'):
            interesting.append(res)
            print(p, code, body)
print('done, interesting:', len(interesting))
